import 'package:local_auth/local_auth.dart';

class LocalAuthService {
  final LocalAuthentication _auth = LocalAuthentication();

  Future<bool> authenticate() async {
    final isSupported = await _auth.isDeviceSupported();
    if (!isSupported) return false;

    final canCheck = await _auth.canCheckBiometrics;
    if (!canCheck) return false;

    return _auth.authenticate(
      localizedReason: '보안을 위해 인증이 필요합니다',
      options: const AuthenticationOptions(
        biometricOnly: false, // PIN/패턴도 허용
        stickyAuth: true,
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'local_auth_service.dart';

class SecureActionButton extends StatelessWidget {
  const SecureActionButton({super.key});

  @override
  Widget build(BuildContext context) {
    return ElevatedButton(
      onPressed: () async {
        final ok = await LocalAuthService().authenticate();
        if (!ok) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('인증 실패')),
          );
          return;
        }
        // 민감 작업 실행
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('승인 완료')),
        );
      },
      child: const Text('보안 작업 실행'),
    );
  }
}
